const DEFAULT_CHECKLIST = [
  'Photo ID (Aadhaar, driving licence or similar)',
  'Previous reports, scans and prescriptions',
  'A list of the medicines you currently take',
  'Your questions, written down so you do not forget',
  'Reach the hospital 10 minutes early'
]
// First match wins; matched against the department name, so it keeps working when the admin renames things.
const CHECKLISTS = [
  { match: /pediatric|paediatric|child/i, items: ['Your child\'s vaccination card', 'Birth and growth records if you have them', 'Previous reports and prescriptions', 'A list of any medicines your child takes', 'Reach the hospital 10 minutes early'] },
  { match: /cardio|heart/i, items: ['Photo ID', 'Previous ECG, echo and blood reports', 'A list of the medicines you currently take', 'Your questions, written down', 'Reach the hospital 10 minutes early'] },
  { match: /ortho|bone|joint/i, items: ['Photo ID', 'Previous X-rays and scans', 'A list of the medicines you currently take', 'Comfortable clothing that is easy to adjust', 'Reach the hospital 10 minutes early'] }
]
export const checklistFor = (department = '') => (CHECKLISTS.find((c) => c.match.test(department))?.items) || DEFAULT_CHECKLIST
